import{_ as o,a0 as p,w as l,s as i,I as t,x as s,a1 as r,A as d}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const x=JSON.parse('{"title":"Cassandra 和 Spark 數據處理一窺 | LCTT x X-CMD","titleTemplate":false,"description":"Cassandra 和 Spark 數據處理一窺 | LCTT (201607) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Cassandra 和 Spark 數據處理一窺 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Cassandra 和 Spark 數據處理一窺 | LCTT (201607) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201607/20160511 An introduction to data processing with Cassandra and Spark","title":"Cassandra 和 Spark 數據處理一窺","tag":"201607","desc":""},"relativePath":"201607/20160511 An introduction to data processing with Cassandra and Spark.md","filePath":"[post].md"}'),e={name:"201607/20160511 An introduction to data processing with Cassandra and Spark.md"};function u(m,a,C,f,k,g){const n=p("Link");return l(),i("div",null,[a[23]||(a[23]=t("h1",{id:"cassandra-和-spark-數據處理一窺",tabindex:"-1"},[s("Cassandra 和 Spark 數據處理一窺 "),t("a",{class:"header-anchor",href:"#cassandra-和-spark-數據處理一窺","aria-label":"Permalink to “Cassandra 和 Spark 數據處理一窺”"},"​")],-1)),a[24]||(a[24]=t("p",null,[t("img",{src:"https://opensource.com/sites/default/files/styles/image-full-size/public/images/life/osdc_520x292_opendata_0613mm.png?itok=mzC0Tb28",alt:""})],-1)),a[25]||(a[25]=t("p",null,"Apache Cassandra 資料庫近來引起了很多的興趣，這主要源於現代雲端軟件對於可用性及性能方面的要求。",-1)),a[26]||(a[26]=t("p",null,"那麼，Apache Cassandra 是什麼？它是一種為高可用性及線性可擴展性優化的分佈式的聯機交易處理 (OLTP) 資料庫。具體説到 Cassandra 的用途時，可以想想你希望貼近用户的系統，比如説讓我們的用户進行交互的系統、需要保證實時可用的程序等等，如：產品目錄，物聯網，醫療系統，以及移動應用。對這些程序而言，下線時間意味着利潤降低甚至導致其他更壞的結果。Netfilix 是這個在 2008 年開源的項目的早期使用者，他們對此項目的貢獻以及帶來的成功讓這個項目名聲大噪。",-1)),a[27]||(a[27]=t("p",null,"Cassandra 於2010年成為了 Apache 軟件基金會的頂級項目，並從此之後就流行起來。現在，只要你有 Cassadra 的相關知識，找工作時就能輕鬆不少。想想看，NoSQL 語言和開源技術能達到企業級 SQL 技術的高度，真讓人覺得十分瘋狂而又不可思議的。這引出了一個問題。是什麼讓它如此的流行？",-1)),t("p",null,[a[1]||(a[1]=s("因為採用了",-1)),r(n,{href:"http://www.allthingsdistributed.com/files/amazon-dynamo-sosp2007.pdf"},{default:d(()=>[...a[0]||(a[0]=[s("亞馬遜發表的 Dynamo 論文",-1)])]),_:1}),a[2]||(a[2]=s("中率先提出的設計，Cassandra 有能力在大規模的硬件及網絡故障時保持實時在線。由於採用了點對點模式，在沒有單點故障的情況下，我們能倖免於機架故障甚至全網中斷。我們能在不影響用户體驗的前提下處理數據中心故障。一個能考慮到故障的分佈式系統才是一個沒有後顧之憂的分佈式系統，因為老實説，故障是遲早會發生的。有了 Cassandra， 我們可以直面殘酷的生活並將之融入資料庫的結構和功能中。",-1))]),a[28]||(a[28]=t("p",null,"我們能猜到你現在在想什麼，“但我只有關係資料庫相關背景，難道這樣的轉變不會很困難嗎？”這問題的答案介於是和不是之間。使用 Cassandra 建立數據模型對有關係資料庫背景的開發者而言是輕車熟路。我們使用表格來建立數據模型，並使用 CQL （ Cassandra 查詢語言）來查詢資料庫。然而，與 SQL 不同的是，Cassandra 支持更加複雜的數據結構，例如嵌套和用户自定義類型。舉個例子，當要儲存對一個小貓照片的點贊數目時，我們可以將整個數據儲存在一個包含照片本身的集合之中從而獲得更快的順序查找而不是建立一個獨立的表。這樣的表述在 CQL 中十分的自然。在我們照片表中，我們需要記錄名字，URL以及給此照片點贊過的人。",-1)),a[29]||(a[29]=t("p",null,[t("img",{src:"https://opensource.com/sites/default/files/resize/screen_shot_2016-05-06_at_7.17.33_am-350x198.png",alt:""})],-1)),a[30]||(a[30]=t("p",null,"在一個高性能系統中，毫秒級處理都能對用户體驗和客户維繫產生影響。昂貴的 JOIN 操作制約了我們通過增加不可預見的網絡調用而擴容的能力。當我們將數據反範式化使其能通過儘可能少的請求就可獲取時，我們即可從磁盤空間成本的降低中獲益並獲得可預期的、高性能應用。我們將反範式化同 Cassandra 一同介紹是因為它提供了很有吸引力的的折衷方案。",-1)),a[31]||(a[31]=t("p",null,"很明顯，我們不會侷限於對於小貓照片的點贊數量。Canssandra 是一款為高併發寫入優化的方案。這使其成為需要時常吞吐數據的大數據應用的理想解決方案。實時應用和物聯網方面的應用正在穩步增長，無論是需求還是市場表現，我們也會不斷的利用我們收集到的數據來尋求改進技術應用的方式。",-1)),a[32]||(a[32]=t("p",null,"這就引出了我們的下一步，我們已經提到了如何以一種現代的、性價比高的方式儲存數據，但我們應該如何獲得更多的動力呢？具體而言，當我們收集到了所需的數據，我們應該怎樣處理呢？如何才能有效的分析幾百 TB 的數據呢？如何才能實時的對我們所收集到的信息進行反饋，並在幾秒而不是幾小時的時間利作出決策呢？Apache Spark 將給我們答案。",-1)),a[33]||(a[33]=t("p",null,"Spark 是大數據變革中的下一步。 Hadoop 和 MapReduce 都是革命性的產品，它們讓大數據界獲得了分析所有我們所取得的數據的機會。Spark 對性能的大幅提升及對代碼複雜度的大幅降低則將大數據分析提升到了另一個高度。通過 Spark，我們能大批量的處理計算，對流處理進行快速反應，通過機器學習作出決策，並通過圖遍歷來理解複雜的遞歸關係。這並非只是為你的客户提供與快捷可靠的應用程序連接（Cassandra 已經提供了這樣的功能），這更是能洞悉 Canssandra 所儲存的數據，作出更加合理的商業決策並同時更好地滿足客户需求。",-1)),t("p",null,[a[5]||(a[5]=s("你可以看看 ",-1)),r(n,{href:"https://github.com/datastax/spark-cassandra-connector"},{default:d(()=>[...a[3]||(a[3]=[s("Spark-Cassandra Connector",-1)])]),_:1}),a[6]||(a[6]=s(" (開源) 並動手試試。若想了解更多關於這兩種技術的信息，我們強烈推薦名為 ",-1)),r(n,{href:"https://academy.datastax.com/"},{default:d(()=>[...a[4]||(a[4]=[s("DataStax Academy",-1)])]),_:1}),a[7]||(a[7]=s(" 的自學課程",-1))]),a[34]||(a[34]=t("hr",null,null,-1)),t("p",null,[a[9]||(a[9]=s("via: ",-1)),r(n,{href:"https://opensource.com/life/16/5/basics-cassandra-and-spark-data-processing"},{default:d(()=>[...a[8]||(a[8]=[s("https://opensource.com/life/16/5/basics-cassandra-and-spark-data-processing",-1)])]),_:1})]),t("p",null,[a[14]||(a[14]=s("作者：",-1)),r(n,{href:"https://twitter.com/rustyrazorblade"},{default:d(()=>[...a[10]||(a[10]=[s("Jon Haddad",-1)])]),_:1}),a[15]||(a[15]=s(",",-1)),r(n,{href:"https://opensource.com/users/dtrapezoid"},{default:d(()=>[...a[11]||(a[11]=[s("Dani Traphagen",-1)])]),_:1}),a[16]||(a[16]=s(" 譯者：",-1)),r(n,{href:"https://github.com/KevinSJ"},{default:d(()=>[...a[12]||(a[12]=[s("KevinSJ",-1)])]),_:1}),a[17]||(a[17]=s(" 校對：",-1)),r(n,{href:"https://github.com/wxy"},{default:d(()=>[...a[13]||(a[13]=[s("wxy",-1)])]),_:1})]),t("p",null,[a[20]||(a[20]=s("本文由 ",-1)),r(n,{href:"https://github.com/LCTT/TranslateProject"},{default:d(()=>[...a[18]||(a[18]=[s("LCTT",-1)])]),_:1}),a[21]||(a[21]=s(" 原創編譯，",-1)),r(n,{href:"https://linux.cn/"},{default:d(()=>[...a[19]||(a[19]=[s("Linux中國",-1)])]),_:1}),a[22]||(a[22]=s(" 榮譽推出",-1))])])}const L=o(e,[["render",u]]);export{x as __pageData,L as default};
